// PlayerMovement.cs is generated by Gemini

using UnityEngine;
using UnityEngine.AI;
using UnityEngine.InputSystem;

public class PlayerMovement : MonoBehaviour
{
    private NavMeshAgent agent;
    private Camera mainCamera;

    void Start()
    {
        agent = GetComponent<NavMeshAgent>();
        mainCamera = Camera.main; 
    }

    void Update()
    {
        if (!GameMenu.IsPlaying) return;
        if (Mouse.current != null && Mouse.current.rightButton.wasPressedThisFrame)
        {
            // 1. Confirms the new Input System is detecting your right-click
            Debug.Log("1. Right-click detected by Input System."); 

            Vector2 mousePos = Mouse.current.position.ReadValue();
            Ray ray = mainCamera.ScreenPointToRay(mousePos);
            RaycastHit hit;

            if (Physics.Raycast(ray, out hit))
            {
                // 2. Confirms the invisible ray actually hit a 3D object with a collider
                Debug.Log("2. Raycast hit object: " + hit.collider.gameObject.name + " at " + hit.point);
                
                agent.SetDestination(hit.point);
                
                // 3. Confirms the NavMeshAgent accepted the destination and calculated a path
                Debug.Log("3. Agent path status: " + agent.pathStatus);
            }
            else 
            {
                Debug.LogWarning("Raycast fired, but hit NOTHING. Check your ground colliders.");
            }
        }
    }
}